package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

public class BrentSolver_solve_TriageGen1Test {

    private UnivariateRealFunction mockFunction;
    private BrentSolver solver;

    @Before
    public void setUp() {
        mockFunction = mock(UnivariateRealFunction.class);
        // Note: Since BrentSolver is a concrete class from Apache Commons Math, 
        // we use the real constructor with a mock function to test the logic.
        solver = new BrentSolver(mockFunction);
    }

    /**
     * Tests the case where sign < 0 (Standard bracketing case).
     * This triggers the call to the internal solve(min, yMin, max, yMax, min, yMin) method.
     */
    @Test
    public void testSolve_StandardBracketing() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 0.5. Root is at 0.5.
        // min = 0, max = 1. f(0) = -0.5, f(1) = 0.5. sign = -0.25 < 0.
        when(mockFunction.value(0.0)).thenReturn(-0.5);
        when(mockFunction.value(1.0)).thenReturn(0.5);

        double root = solver.solve(0.0, 1.0);

        assertEquals(0.5, root, 1e-10);
    }

    /**
     * Tests the case where sign == 0 (One of the endpoints is exactly zero).
     */
    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(0) = 0, f(1) = 1. sign = 0.
        when(mockFunction.value(0.0)).thenReturn(0.0);
        when(mockFunction.value(1.0)).thenReturn(1.0);

        double root = solver.solve(0.0, 1.0);

        assertEquals(0.0, root, 0.0);
    }

    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(0) = -1, f(1) = 0. sign = 0.
        when(mockFunction.value(0.0)).thenReturn(-1.0);
        when(mockFunction.value(1.0)).thenReturn(0.0);

        double root = solver.solve(0.0, 1.0);

        assertEquals(1.0, root, 0.0);
    }

    /**
     * Tests the case where sign > 0 and yMin is within functionValueAccuracy.
     * This covers the branch: if (sign > 0) { if (Math.abs(yMin) <= functionValueAccuracy) ... }
     */
    @Test
    public void testSolve_SignPositive_MinCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // We need to control functionValueAccuracy. In BrentSolver, this is typically a small constant.
        // Since we can't easily change the private field via standard API, we assume a very small value.
        // Let's assume accuracy is 1e-14.
        double min = 0.0;
        double max = 1.0;
        double yMin = 1e-15; 
        double yMax = 1.0;

        when(mockFunction.value(min)).thenReturn(yMin);
        when(mockFunction.value(max)).thenReturn(yMax);

        double root = solver.solve(min, max);

        assertEquals(min, root, 0.0);
    }

    /**
     * Tests the case where sign > 0 and yMin is NOT close to zero.
     * This covers the branch: else if (true) { setResult(max, 0); ret = max; }
     * Note: The provided code has a logical 'else if (true)' which forces this branch.
     */
    @Test
    public void testSolve_SignPositive_MinNotCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        double min = 0.0;
        double max = 1.0;
        double yMin = 0.5; 
        double yMax = 1.0;

        when(mockFunction.value(min)).thenReturn(yMin);
        when(mockFunction.value(max)).thenReturn(yMax);

        double root = solver.solve(min, max);

        assertEquals(max, root, 0.0);
    }

    /**
     * Tests the behavior when min > max to ensure verifyInterval is called.
     * Note: verifyInterval is a private/protected method; assuming it throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidInterval() throws MaxIterationsExceededException, FunctionEvaluationException {
        solver.solve(1.0, 0.0);
    }
}
